import unittest

from solucao import tem
from solucao import quantos_estao


class TestEstaNaLista(unittest.TestCase):
    def test_item_que_esta(self):
        """tem devolve True quando o item esta na lista"""
        self.assertTrue(tem(["uva", "pera", "manga"], "pera"))

    def test_item_que_nao_esta(self):
        """tem devolve False quando o item nao esta na lista"""
        self.assertFalse(tem(["uva", "pera", "manga"], "kiwi"))

    def test_quantos_dos_pedidos_estao(self):
        """quantos_estao devolve quantos dos pedidos estao na lista"""
        self.assertEqual(quantos_estao(["uva", "pera"], ["pera", "kiwi", "uva"]), 2)

    def test_nenhum_pedido_esta(self):
        """quantos_estao devolve 0 quando nenhum pedido esta"""
        self.assertEqual(quantos_estao(["uva"], ["kiwi", "pera"]), 0)

